\label{lem:shuffleIdentity}
Let $X: [0,T] \to \mathbb{R}^d$ be a continuous curve of bounded variation, then for every $a,b \in T(\mathbb{R}^d)$
\begin{align*}
  \Big\langle S(X)_{0,T}, a \Big\rangle
  \Big\langle S(X)_{0,T}, b \Big\rangle
  =
  \Big\langle S(X)_{0,T}, a \shuffle b \Big\rangle
\end{align*}

\label{lem:chen}
For curves $X: [0,T] \to \mathbb{R}^d, Y: [0,T] \to \mathbb{R}^d$ denote
their concatenation
\begin{align*}
  X \sqcup Y: [0,2T] \to \mathbb{R}^d,
\end{align*}
as $X_\cdot$ on $[0,T]$ and $Y_{\cdot-T} - Y_0 + X_T$ on $[T,2T]$.
Then
\begin{align*}
  S(X \sqcup Y)_{0,2T} = S(X)_{0,T} \cdot S(Y)_{0,T}.
\end{align*}

\label{lem:oneToOne}
The space of all multilinear maps on $\mathbb{R}^{d} \times \dots \times \mathbb{R}^{d}$ ($n$-times)
is in a one-to-one correspondence with homogeneous polynomials of order $n$ in the non-commuting variables $x_1,\dots,x_d$
by the following bijection
\begin{align*}
  \psi \mapsto \mathsf{poly}(\psi) := \sum_{i_1, \dots, i_n \in \{1,\dots,d\}} \psi(e_{i_1}, e_{i_2}, \dots, e_{i_n}) x_{i_1} \cdot x_{i_2} \cdot .. \cdot x_{i_n},
\end{align*}
with $e_i$ being the $i$-th canonical basis vector of $\mathbb{R}^d$.

Let
\begin{align*}
  GL(\mathbb{R}^d) = \{ A \in \mathbb{R}^{d\times d} : \det( A ) \not= 0 \},
\end{align*}
be the general linear group of $\mathbb{R}^d$.

\label{def:invariant}
For $w \in \mathbb{N}$,
we call $\phi \in T(\R^\ds)$ an \textbf{GL invariant of weight $w$} if
\begin{align*}
  \Big\langle S(A X)_{0,T}, \phi \Big\rangle = (\det A)^w \Big\langle S(X)_{0,T}, \phi \Big\rangle
\end{align*}
for all $A \in \operatorname{GL}(\mathbb{R}^d)$.

\label{def:action}
Define a linear action of $GL(\mathbb{R}^d)$ on $T((\R^\ds))$ and $T(\R^\ds)$,
by specifying on monomials
\begin{align*}
  A x_{i_1} .. x_{i_n}
  &:=
  \sum_j (A e_{i_1})_{j_1} x_{j_1} .. (A e_{i_n})_{j_n} x_{j_n} \\
  &=
  \sum_j A_{j_1 i_1} .. A_{j_n i_n} x_{j_1} .. x_{j_n}.
\end{align*}

For all $A \in \mathbb{R}^{d \times d}$ and any curve $X$,
\begin{align*}
  \Big\langle S(A X)_{0,T}, \phi \Big\rangle
  =
  \Big\langle S(X)_{0,T}, A^\top \phi \Big\rangle.
\end{align*}

It is clear by definition that the left hand side of \eqref{eq:GspansT} is included in $\pi_n T((\R^\ds))$.
We show the other direction and use ideas of \cite[Proposition 4]{bib:CF2010}. 

Let $x_{i_n} \cdot \ldots \cdot x_{i_1} \in \pi_n T((\R^\ds))$ be given.
Let $X$ be the piecewise linear path that results from the concatenation of the vectors $t_1 e_{i_1}, t_2 e_{i_2}$ up to $t_n e_{i_n}$,
where $e_i, i=1,..,d$ is the standard basis of $\mathbb{R}^d$.
Its signature is given by (see for example \cite[Chapter 6]{bib:FV2010})
\begin{align*}
  S(X)_{0,1} = \exp( {t_n x_{i_n}} ) \cdot \ldots \cdot \exp( t_1 x_{i_1} ) =: \phi(t_1, \dots, t_n),
\end{align*}
where the exponential function is defined by its power series.

Then
\begin{align*}
  \frac{d}{dt_n} \dots \frac{d}{dt_1} \phi(0,\dots,0) = x_{i_n} \cdot \ldots \cdot x_{i_1}.
\end{align*}
Combining this with the fact that left hand side of \eqref{eq:GspansT} is a closed set we get that
\begin{align*}
  x_{i_n} \cdot \ldots \cdot x_{i_1}
  \in 
  \operatorname{span}\{ \pi_n( S(X) _{0,1} ) : X \text{ curve } \}.
\end{align*}

These elements span $\pi_n T((\R^\ds))$, which finishes the proof.

\label{lem:projectionIsInvariant}
If $\phi \in T(\R^\ds)$ satisfies
\begin{align*}
  B \phi = \phi,
\end{align*}
for some $B \in GL(\mathbb{R}^d)$ then
\begin{align*}
  B \pi_n \phi = \pi_n \phi,
\end{align*}
for all $n \ge 1$.

\label{lem:multi}
For $\psi: (\mathbb{R}^d)^{\times n} \to \mathbb{R}$ multilinear
and
$A \in GL(\mathbb{R}^d)$,
\begin{align*}
  \mathsf{poly}[ \psi( A \cdot ) ] = A^\top \mathsf{poly}[ \psi ].
\end{align*}

\label{thm:linearBasis}

 The space of multilinear maps
 \begin{align*}
   \psi: \underbrace{\mathbb{R}^d \times \dots \times \mathbb{R}^d}_{n \text{ times}} \to \mathbb{R}
 \end{align*}
 that satisfy
 \begin{align*}
   \psi(A v_1, A v_2, \dots, A v_n) = (\det A)^w \psi(v_1, v_2, \dots, v_n)
 \end{align*}
 for all $A \in \operatorname{GL}(V)$ and $v_1, \dots, v_n \in V$
 is non-empty if and only if $n = w d$ for some integer $w \ge 1$.

In that case, a linear basis is given by
\begin{align*}
  \{ v \mapsto \det[ v_{C_1} ]  .. \det[ v_{C_w} ] \}
\end{align*}
where
$C_i$ are the columns of $\Sigma$,
and
$\Sigma$ ranges over all standard Young tableaux corresponding to the partition $\lambda = \underbrace{(w, w, .., w)}_{d \text{ times}}$ of $n$.

Here, for a sequence $C = (c_1,..,c_d)$, $v_C$ denotes the matrix
of column vectors $v_{c_i}$, i.e.
\begin{align*}
  v_C = (v_{c_1}, .., v_{c_d}).
\end{align*}

Write $V = (\mathbb{R}^d)^*$, the dual space of $\mathbb{R}^d$.
Every $\phi \in V^{\otimes n}$ that satisfies
\begin{align}
  \label{eq:x}
  A \phi = (\det A)^w \phi,
\end{align}
clearly spans a one-dimensional irreducible representation of $GL(V)$.

Hence, we need to investigate all one-dimensional irreducible representation 
of $GL(V)$ contained in $V^{\otimes n}$ (and it will turn out that all of them satisfy \eqref{eq:x}).

The (diagonal) action of $GL(V)$ on $V^{\otimes n}$ is best understood,
by simultaneously studying the left action of $S_n$ on $V^{\otimes n}$ given
by
\begin{align*}
  \tau \cdot v_1 \otimes .. \otimes v_n
  :=
  v_{\tau^{-1}(1)} \otimes .. \otimes v_{\tau^{-1}(n)}.
\end{align*}






By Schur-Weyl duality, \cite[Theorem 6.4.5.2]{bib:Lan2012}, as $S_n \times GL(V)$ modules,
\begin{align}
  \label{eq:schurWeyl}
  V^{\otimes n} \simeq \bigoplus_{\lambda \vdash n} S^\lambda \otimes V^\lambda,
\end{align}
where the sum is over integer partitions $\lambda$ of $n$,
the $S^\lambda$ are irreducible representations of $S_n$, to be detailed below
and the $V^\lambda$ are irreducible representations of $GL(V)$.

The exact form of the latter is irrelevant here,
we only need to know that $V^\lambda$ is one-dimensional if
and only if $\lambda = (w,..,w)$, $d$-times, for some integer $w \ge 1$,
\cite[p.21]{bib:DC1970}.
This gives the condition $n = w d$ in the statement. We assume this to hold from now on.


We are hence left with understanding the unique copy of the ``Specht module'' $S^\lambda$ inside of $V^{\otimes n}$.

We sketch its classical construction.

Let us recall that a \textbf{tabloid} is an equivalence class of Young tableaux modulo
permutations leaving the set of entries in each row invariant \cite[Chapter 2]{bib:Sag2013}.
\footnote{
  One can also think of a tabloid as the following element of the vector space spanned by Young tableaux,
  \begin{align*}
    \{ t \} = \sum_{\pi} \pi t.
  \end{align*}
  Here the sum is over all permutations $\pi$ that leave the elements of each \emph{row} of $t$ unchanged.
}

For $t$ a Young tableau denote $\{ t \}$ its tabloid, so for example
\begin{align*}
  \left\{
  \begin{ytableau}
    1  & 3 \\
    2  & 4
  \end{ytableau}
  \right\}
  =
  \left\{
  \begin{ytableau}
    1  & 3 \\
    4  & 2
  \end{ytableau}
  \right\}
  =
  \left\{
  \begin{ytableau}
    3  & 1 \\
    2  & 4
  \end{ytableau}
  \right\}
  =
  \left\{
  \begin{ytableau}
    3  & 1 \\
    4  & 2
  \end{ytableau}
  \right\}.
\end{align*}

The symmetric group $S_n$ acts on Young tableaux as
\begin{align*}
  (\tau \cdot t)_{ij} := \tau( t_{ij} ).
\end{align*}
For example
\begin{align*}
  (234) \cdot
  \begin{ytableau}
    2  & 4 \\
    1  & 3
  \end{ytableau}
  =
  \begin{ytableau}
    3  & 2 \\
    1  & 4
  \end{ytableau}
\end{align*}
It then acts on tabloids by $\tau \cdot \{t\} := \{ \tau \cdot t \}$.
Define for a Young tableau $t$ 

\begin{align*}
  e_t := \sum_{\pi} \operatorname{sign}(\pi) \pi \cdot \{ t \},
\end{align*}
where the sum is over all $\pi \in S_n$ that leave the set of values in each \emph{column} invariant.

For example with 
\begin{align*}
  t =
  \begin{ytableau}
    1  & 2 \\
    3  & 4
  \end{ytableau}
\end{align*}
we get
\begin{align*}
  e_t
  =   
  \{ t \}
  +
  (1 3) \cdot \{ t \}
  +
  (2 4) \cdot \{ t \}
  +
  (1 3) (2 4) \cdot \{t\}.
\end{align*}

Then
\begin{align*}
  \operatorname{Irrep}_{(w,..,w)}
  := \operatorname{span}\{ e_t : t \text{ Young tableau of shape } (w,..,w) \}
\end{align*}
is an irreducible representation of $S_n$ and
\begin{align*}
  \{ e_t : t \text{ standard Young tableau of shape $(w,..,w)$}  \},
\end{align*}
forms a basis \cite[Theorem 2.5.2]{bib:Sag2013}.
This concludes the reminder on representation theory for $S_n$.



















Define the map $\iota$ from the space of tabloids of shape $(w,..,w)$ into $V^{\otimes n}$ as follows,

\begin{align*}
  \iota( \{ t \} )
  :=
  e_{j_1}^* \otimes .. \otimes e_{j_n}^*,
\end{align*}
where $e_i^*$ is the canonical basis of $V$ and
\begin{align*}
  j_\ell = i \qquad \Leftrightarrow \qquad \ell \in \text{ $i$-th row of } \{ t \}.
\end{align*}
For example
\begin{align*}
  \iota\left(
    \left\{
      \begin{ytableau}
      1 & 2 & 5\\
      3 & 4 & 6
      \end{ytableau}
    \right\}
  \right)
  =
  e_1^* \otimes e_1^* \otimes e_2^* \otimes e_2^* \otimes e_1^* \otimes e_2^*.
\end{align*}
This is a homomorphism of $S_n$ representations.
Indeed,
\begin{align*}
  \iota( \tau \cdot \{t\} )
  =
  e_{j_1}^* \otimes .. \otimes e_{j_n}^*,
\end{align*}
with
\begin{align*}
  j_\ell = i &\Leftrightarrow \ell \in \text{ $i$-th row of } \tau \cdot \{t\}.

\end{align*}




On the other hand
\begin{align*}
  \tau \cdot \iota( \{t\} )
  &=
  \tau \cdot e_{r_1}^* \otimes .. \otimes e_{r_n}^* \\
  &=

  e_{p_1}^* \otimes .. \otimes e_{p_n}^*,
\end{align*}
with $p_\ell := r_{\tau^{-1}(\ell)}$
and
\begin{align*}
  p_\ell = i &\Leftrightarrow r_{\tau^{-1}(\ell)} = i \\
             &\Leftrightarrow \tau^{-1}(\ell) \in \text{ $i$-th row of } \{t\} \\
             &\Leftrightarrow \ell \in \text{ $i$-th row of } \tau \cdot \{t\}.




\end{align*}
So indeed $\iota( \tau \cdot \{t\} ) = \tau \cdot \iota \{t\} )$,
and $\iota$ is a homomorphism of $S_n$ representations.

It is a bijection from the space of $(w,..,w)$ tabloids
into the space spanned by the vectors
\begin{align*}
  e_{i_1} \otimes .. \otimes e_{i_n} : \#\{ \ell : i_\ell = j \} = w, \quad j = 1, .., d.
\end{align*}
Restricting to $\operatorname{Irrep}_{(w,..,w)}$ then yields an isomorphism of irreducible $S_n$ representations.
Hence, $\iota( \operatorname{Irrep}_{(w,..,w)} )$ is the (unique) realization of $S^\lambda$ inside of $V^{\otimes n}$ in \eqref{eq:schurWeyl}.
We finish by describing its image.

Consider the standard Young tableau $t_{first}$ of shape $(w,w,..,w)$ obtained by filling the columns from left to right, i.e.
\begin{align*}
  t_{first}
  := 
  \raisebox{40pt}[80pt][80pt]{
  \ytableausetup{mathmode, boxsize=3em}
  \begin{ytableau}
    1   & d + 1 & ..& .. & .. \\
    2   & d + 2 & ..& .. & ..   \\
    ..  & ..      & ..& .. & .. \\
    d & 2 d   & ..& .. & n
  \end{ytableau}
  }
\end{align*}

Clearly, for any (standard) Young tableau $t$ there exists unique $\sigma_t \in S_n$ such that
\begin{align*}
  \sigma_t \cdot t_{first} = t.
\end{align*}

We claim
\begin{align*}
  \iota( e_t )
  =
  \Bigl( v \mapsto \det[ v_{\sigma_t(1)} .. v_{\sigma_t(d)} ] \cdot ... \cdot \det[ v_{\sigma_t((w-1)d + 1)} .. v_{\sigma_t(n)}] \Bigr).
\end{align*}
Indeed, since $\iota$ is a homomorphism of $S_n$ representation,
\begin{align*}
  \iota( \sigma_t \cdot e_{t_{first}} )(v_1,..,v_n)
  &=
  \iota( e_{t_{first}} )(v_{\sigma_t(1)},..,v_{\sigma_t(n)})
\end{align*}
It remains to check
\begin{align*}
  \iota( e_{t_{first}} ) = \det[v_1..v_d] ..\det[v_{(w-1)d+1} .. v_n].
\end{align*}
Every $\pi \in S^n$ that is column-preserving for $t_{first}$
can be written as
the product $\pi_1 \cdot .. \cdot \pi_w$,
with $\pi_j$ ranging over the permutations of the entries of the $j$-th column $t_{first}$.


Then

\begin{align*}
  \iota( e_{t_{first}} )(v_1,..,v_n)
  &=
  \sum_\pi \operatorname{sign} \pi\ \iota( \pi \{t\} )( v_1, .., v_n ) \\
  &=
  \sum_{\pi_j} \prod_j \operatorname{sign} \pi_j\ \iota( \pi_1 .. \pi_w \{t\} )( v_1, .., v_n ) \\
  &=
  \sum_{\pi_j} \prod_j \operatorname{sign} \pi_j\ 
  e^*_{\pi^{-1}_1(1)} \otimes .. \otimes e^*_{\pi^{-1}_1(d)}
  \otimes
  e^*_{(\pi^{-1}_2(d+1) \operatorname{mod} d) + 1} \otimes\cdots

  \\&\qquad\qquad\cdots \otimes e^*_{(\pi^{-1}_w(n) \operatorname{mod} d) + 1} (v_1,..,v_n) \\
  &=
  \det[v_1..v_d] ..\det[v_{(w-1)d+1} .. v_n],
\end{align*}
as desired.

\label{prop:glInvariants}
A linear basis for the space of $GL$ invariants of order $n = w d$ is given by
\begin{align*}
  \sum_{i_1,\dots,i_n \in \{1,\dots,d\}} g_\Sigma(i_1,i_2,\dots,i_n) x_{i_1} x_{i_2} \dots x_{i_n},
\end{align*}
where
\begin{align*}
  g_\Sigma(v) = \det[ v_{C_1} ]  .. \det[ v_{C_w} ],
\end{align*}
where
$C_i$ are the columns of $\Sigma$,
and
$\Sigma$ ranges over all standard Young tableaux corresponding to the partition $\lambda = \underbrace{(w, w, .., w)}_{d \text{ times}}$ of $n$.

\label{rem:interpretation}

Let us make clear that from the perspective of data analysis,
the ``invariant'' of interest is really the action of this element in $T(\R^\ds)$
on the signature of a curve.

In this example, the real number
\begin{align*}
  \Big\langle S(X)_{0,T}, \word{12} - \word{21} \Big\rangle
  =  
  \int_0^T \int^{r_2} dX^1_{r_1} dX^2_{r_2}
  -
  \int_0^T \int^{r_2} dX^1_{r_1} dX^2_{r_2},

\end{align*}
changes only by the determinant of $A \in GL(\mathbb{R}^2)$ when
calculating it for the transformed curve $A X$:
\begin{align*}
  \Big\langle S(A X)_{0,T}, \word{12} - \word{21} \Big\rangle = \det(A)\ \Big\langle S(X)_{0,T}, \word{12} - \word{21} \Big\rangle.
\end{align*}

\label{lem:dxw1}

In any dimension $d$
and for any $r=0,1,..,d-1$
\begin{align*}
  \firstInvariant{d}(x_1,..,x_d)
  =
  (-1)^{r}
  \sum_{j=1}^{d}
  (-1)^{j+1} \mathsf{InsertAfter}(x_j,r) \firstInvariant{d-1}( x_1, .., \widehat{x_j} .., x_d ),
\end{align*}
where $\widehat{x_j}$ denotes the omission of that argument.

For $d$ odd,
\begin{align*}
  \firstInvariant{d}(x_1,..,x_d)
  &=
  \sum_{j=1}^d
  (-1)^{j+1}
  x_j \shuffle \firstInvariant{d-1}( x_1, .., \widehat{x_j} .., x_d ).
\end{align*}

For completeness, we also note the related \emph{de Bruijn's formula}.
For $d$ even,
\begin{align*}
  \firstInvariant{d}(x_1,..,x_d)
  =
  \operatorname{Pf}_\shuffle[ A ],
\end{align*}
where
\begin{align*}
  A_{ij}
  = 
  \firstInvariant{2}(x_i,x_j),
\end{align*}
and the Pfaffian (with respect to the shuffle product), is
\begin{align*}
  \operatorname{Pf}_\shuffle[ A ]
  =
  \frac{1}{2^{d/2} (d/2)!}
  \sum_{\sigma \in S_{d}} \operatorname{sign}(\sigma)

  A_{\sigma(1),\sigma(2)}
  \shuffle
  A_{\sigma(3),\sigma(4)}
  \shuffle
  ..
  \shuffle
  A_{\sigma(d-1),\sigma(d)}.
\end{align*}

For a proof see \cite{bib:DB1955}
and \cite{bib:LT2002}.

\label{lem:closedCurveOddDimension}
If the ambient dimension $d$ is odd and the curve $X$ is closed (i.e. $X_T = X_0$) then
\begin{align*}
  \Big\langle S(X)_{0,T}, \firstInvariantd \Big\rangle = 0.
\end{align*}

\label{lem:lastPoint}
If the ambient dimension $d$ is even, then for any curve $X$
\begin{align*}
  \Big\langle S(X)_{0,T}, \firstInvariantd \Big\rangle
  =
  \Big\langle S(\bar X)_{0,T}, \firstInvariantd \Big\rangle,
\end{align*}
where $\bar X$ is $X$ concatenated with the straight line connecting $X_T$ to $X_0$.

Let $\bar X$ be parametrized on $[0,2T]$ as follows: $\bar X = X$ on $[0,T]$
and it is the linear path connecting $X_T$ to $X_0$ on $[T,2T]$.

By translation invariance we can assume $X_0 = 0$ and by $GL(\mathbb{R}^d)$-invariance that $X_T$ lies on the $x_1$ axis.
Then the only component of $\bar X$ that is non-constant on $[2T,T]$ is the first one, $\bar X^1$.

By Lemma~\ref{lem:dxw1}
\begin{align*}
  \firstInvariant{d}
  =
  -
  \sum_{j=1}^d
  (-1)^{j+1}
  \firstInvariant{d-1}(x_1, .., \hat x_j, .. x_d) x_j.
\end{align*}
Letting the summands act on $S(\bar X)_{0,t}$ we get $\pm 1$ times
\begin{align*}
  \int_0^t \Big\langle S(\bar X)_{0,r} \firstInvariant{d-1}(x_1, .., \hat x_j, .. x_d) \Big\rangle d\bar X^j_r.
\end{align*}
For $j\not=1$ these expressions are constant on $[T,2T]$, since we arranged things so that those
$\bar X^j$ do not move on $[T,2T]$.

But also for $j=1$ this expression is constant on $[T,2T]$.
Indeed, the integrand 
\begin{align*}
  \Big\langle S(\bar X)_{0,r} \firstInvariant{d-1}(x_2, x_3, .., x_d) \Big\rangle,
\end{align*}
is zero on $[T,2T]$, since $X$, projected on the $x_2-..-x_d$ hyperplane, is a closed curve,
and so Lemma~\ref{lem:closedCurveOddDimension} applies.

\label{lem:invariantVolume}
Let $X$ be the piecewise linear curve
through $p_0,..,p_{d} \in \mathbb{R}^d$.
Then
\begin{align*}
  \Big\langle S(X)_{0,T}, \firstInvariantd \Big\rangle
  =
 \det\left[
   \begin{matrix}
     1 & 1 & .. & 1 \\
     p_0 & p_1 & .. & p_{d}
   \end{matrix}
 \right]
\end{align*}


First, for any $v \in \mathbb{R}^d$,
\begin{align*}
 \det\left[
   \begin{matrix}
     1 & 1 & .. & 1 \\
     p_0 + v & p_1 + v & .. & p_{d} + v
   \end{matrix}
 \right]
 =
 \det\left[
   \begin{matrix}
     1 & 1 & .. & 1 \\
     p_0 & p_1 & .. & p_{d}
   \end{matrix}
 \right].
\end{align*}



Since the signature is also invariant to translation, we can therefore assume $p_0 = 0$.

Now both sides of the statement transform the same way under the action of $GL(\mathbb{R}^d)$ on
the points $p_1,..p_d$.

It is then enough to prove this for
\begin{align*}
  p_0 &= 0 \\
  p_1 &= e_1 \\
  p_2 &= e_1 + e_2 \\
      &.. \\
  p_{d} &= e_1 + .. + e_d.
\end{align*}

Now, for this particular choice of points the right hand side is clearly equal to $1$.
For the left hand side, the only non-zero term is
\begin{align*}
  \Big\langle S(X)_{0,T}, \word{12} .. \word{d} \Big\rangle
  &=
  \int dX^1 .. dX^d \\
  &= 1.
\end{align*}

\label{lem:generalPiecewiseLinearCurve}
Let $X$ be the piecewise linear curve through,
$p_0,..,p_n \in \mathbb{R}^d$, with $n \ge d$.

Then,
\begin{align}
  \label{eq:invDet}
  \Big\langle S(X)_{0,T}, \firstInvariantd \Big\rangle
  =
  \sum_i
   \det\left[
     \begin{matrix}
       1 & 1 & .. & 1 \\
       p_{i_0} & p_{i_1} & .. & p_{i_{d}}
     \end{matrix}
   \right].
\end{align}
Here, for $d$ even, the subsequences $i$ are chosen as follows:
\begin{align*}
  i_0 = 0
\end{align*}
and $i_1,..,i_{d}$ ranges over all possible increasing
subsequences of $1,2,..,n$ such that
for $\ell$ odd: $i_\ell + 1 = i_{\ell+1}$

For $d$ odd, they are chosen as follows:
\begin{align*}
  i_0 &= 0 \\
  i_{d} &= n,
\end{align*}
and $i_1,..,i_{d-1}$ ranges over all possible increasing
subsequences of $1,2,..,n-1$ such that
for $\ell$ odd: $i_\ell + 1 = i_{\ell+1}$

In both the odd and the even case,
there are
\begin{align*}
  \binom{\lfloor d/2 \rfloor + n - d - 1 }{ n - d -1 }
\end{align*}
indices summed over.


	Let $X: [0,T] \to \mathbb{R}^d$ be any curve.
	Define its \textbf{signed volume} to be the following limit, if it exists,
	\begin{align*}
	  \operatorname{Signed-Volume}(X)
