  \end{pmatrix}.
\end{align}
Here, for a matrix $C$ of non-commuting variables,
\begin{align*}
  \det C := \sum_\tau \operatorname{sign} \tau \prod_i C_{i \tau(i)}.
\end{align*}

This invariant is of homogeneity $d$.
The following lemma tells us that 
we can write
$\firstInvariant{d}$ in terms of expressions on lower homogeneities.




To state it, we first define the operation $\mathsf{InsertAfter}(x_i,r)$ 
on monomials 
of order $n \ge r$, 
as the insertion of the variable $x_i$ after position $r$, and extend it linearly.
For example
\begin{align*}
  \mathsf{InsertAfter}(x_1,1) \firstInvariant{2}(x_2,x_3)
  &=
  \mathsf{InsertAfter}(x_1,1) \Big( x_2 x_3 - x_3 x_2 \Big) \\
  &=
  x_2 x_1 x_3 - x_3 x_1 x_2.
\end{align*}


\begin{lemma}
  \label{lem:dxw1}

  In any dimension $d$
  and for any $r=0,1,..,d-1$
  \begin{align*}
    \firstInvariant{d}(x_1,..,x_d)
    =
    (-1)^{r}
    \sum_{j=1}^{d}
    (-1)^{j+1} \mathsf{InsertAfter}(x_j,r) \firstInvariant{d-1}( x_1, .., \widehat{x_j} .., x_d ),
  \end{align*}
  where $\widehat{x_j}$ denotes the omission of that argument.

  For $d$ odd,
  \begin{align*}
    \firstInvariant{d}(x_1,..,x_d)
    &=
    \sum_{j=1}^d
    (-1)^{j+1}
    x_j \shuffle \firstInvariant{d-1}( x_1, .., \widehat{x_j} .., x_d ).
  \end{align*}
\end{lemma}
\begin{remark}
  For completeness, we also note the related \emph{de Bruijn's formula}.
  For $d$ even,
  \begin{align*}
    \firstInvariant{d}(x_1,..,x_d)
    =
    \operatorname{Pf}_\shuffle[ A ],
  \end{align*}
  where
  \begin{align*}
    A_{ij}
    = 
    \firstInvariant{2}(x_i,x_j),
  \end{align*}
  and the Pfaffian (with respect to the shuffle product), is
  \begin{align*}
    \operatorname{Pf}_\shuffle[ A ]
    =
    \frac{1}{2^{d/2} (d/2)!}
    \sum_{\sigma \in S_{d}} \operatorname{sign}(\sigma)

    A_{\sigma(1),\sigma(2)}
    \shuffle
    A_{\sigma(3),\sigma(4)}
    \shuffle
    ..
    \shuffle
    A_{\sigma(d-1),\sigma(d)}.
  \end{align*}

  For a proof see \cite{bib:DB1955}
  and \cite{bib:LT2002}.
\end{remark}

